OUT_NO , CUSTOMS_REPORT_NO , LAST_POD_DATE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='STATUS_ORDER_CARGO' AND CODE = LAST_POD_STATUS) AS LAST_POD_STATUS , LAST_POD_RAQ_DATE , APPROVAL_DATE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='CARRYOUT_TYPE' AND CODE = OUT_CLASS) AS OUT_CLASS , OUT_APPROVAL_NO , OD_JOB_NO , IN_NO , OUT_PLAN_NO , CARGO_REFERENCE_NO , BL_NO , MBL_NO , DO_NO , DO_DATE , CUSTOMS_CODE , CUSTOMS_DPT_CODE , CUSTOMER_CODE , CUSTOMER_NAME , BROKER_CODE , BROKER_NAME , (SELECT CODE FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='UNIT_PIECES' AND CODE = PKG_TYPE) AS PKG_TYPE , APPROVAL_CT , APPROVAL_WT , APPROVAL_CBM , OUT_CT , OUT_WT , OUT_CBM , CARRYOUT_DATE , CARRYOUT_TIME , APPROVAL_DUTY , APPROVAL_APPRAISE_VALUE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='PAYMENT_TYPE' AND CODE = INS_PAYMENT_TYPE) AS INS_PAYMENT_TYPE , CURRENCY_CODE , INS_PAYMENT_YN , INSPECT_YN , HS_CODE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='IMPORT_REQUIREMENT_LAW_CODE' AND CODE = CRITERIA_CODE) AS CRITERIA_CODE , INOUT_DATE_DIFF , REMARKS_1 , REMARKS_2 , REMARKS_3 , REFERENCE_NO , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME , REGISTER_USER_NAME , UPDATE_USER_NAME , SD_TYPE , CARRYIN_DATE , CARRYIN_TIME , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='CD_TYPE' AND CODE = CD_TYPE) AS CD_TYPE , SIMPLE_CNT , GENERAL_CNT , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='CCL_ECOMMERCE_TYPE' AND CODE = ECM_TYPE) AS ECM_TYPE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='USE_GUBN' AND CODE = CD_USE_TYPE) AS CD_USE_TYPE , IMPORT_EXPORT_CLASS , VESSEL_FLIGHT , VOYAGE , AR_DATE , AR_TIME , COMMODITY_ITEM_LOC , LOCATION_PLACE , BIG_SIZE_YN , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='SE_INSPECTION_CODE' AND CODE = SE_INSPECTION_CODE ) AS SE_INSPECTION_CODE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='INSPECTION_TYPE' AND CODE = INSPECTION_TYPE ) AS INSPECTION_TYPE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='INSPECTION_TYPE' AND CODE = INSPECTION_TYPE_A ) AS INSPECTION_TYPE_A , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='INSPECTION_TYPE' AND CODE = INSPECTION_TYPE_B ) AS INSPECTION_TYPE_B , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='SE_INSPECTION_CODE' AND CODE = XRAY_INSPECTION_CODE ) AS XRAY_INSPECTION_CODE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='XRAY_LINE_NO' AND CODE = XRAY_LINE_NO ) AS XRAY_LINE_NO , SPECIAL_CODE_1 , SPECIAL_CODE_2 , SPECIAL_CODE_3 , ORIG_COUNTRY , DELIVERY_TERMS , COMPANY_BUSINESS_NO , COMPANY_NAME , COMPANY_PRESIDENT , CNTR_NO_APP , HOLD_YN , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='HOLD_CODE' AND CODE = HOLD_CODE ) AS HOLD_CODE , HOLD_REASON , HOLD_RELEASE_YN , HOLD_RELEASE_ATTN , HOLD_RELEASE_DATE , FILE_SHARE FROM (
) AA

