+'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='INSPECTION_TYPE' AND CODE = INSPECTION_TYPE_B ) AS INSPECTION_TYPE_B , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='SE_INSPECTION_CODE' AND CODE = XRAY_INSPECTION_CODE ) AS XRAY_INSPECTION_CODE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='XRAY_LINE_NO' AND CODE = XRAY_LINE_NO ) AS XRAY_LINE_NO , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='XRAY_INSPECTION_TYPE' AND CODE = XRAY_CHECK ) AS XRAY_CHECK , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='SE_INSPECTION_CODE' AND CODE = PALN5EM_INSPECTION_CODE ) AS PALN5EM_INSPECTION_CODE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='CD_TYPE' AND CODE = CD_TYPE) AS CD_TYPE , SIMPLE_CNT , GENERAL_CNT , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='CCL_ECOMMERCE_TYPE' AND CODE = ECM_TYPE) AS ECM_TYPE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='USE_GUBN' AND CODE = CD_USE_TYPE) AS CD_USE_TYPE , BIG_SIZE_YN , AMOUNT_USD , XRAY_SCAN_CT , XRAY_IMAGE_CT , CARRYIN_DATE , CARRYIN_TIME , OUT_NOTICE_DATE , PERIOD_OVER_DATE , CUSTOMER_CODE , CUSTOMER_NAME , FWD_CODE , FWD_NAME , (SELECT CODE FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='UNIT_PIECES' AND CODE = PKG_TYPE) AS PKG_TYPE , EX_CT , EX_WT , EX_CBM , CT , WT , CBM , (SELECT CODE FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='ABNORMALITY_CODE' AND CODE = ACCIDENT_CLASS) AS ACCIDENT_CLASS , ACCIDENT_CT , ACCIDENT_WT , ACCIDENT_CBM , STOCK_CT , STOCK_WT , STOCK_CBM , CARRYOUT_DATE , CARRYOUT_TIME , REMARKS_1 , REMARKS_2 , REMARKS_3 , REFERENCE_NO , MGN_ISSUE_YN , ASSIGN_YN , CRIME_SELECTION_YN , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME , FILE_SHARE , REGISTER_USER_NAME , UPDATE_USER_NAME FROM (
