ntCode} AND GROUP_CODE ='USE_GUBN' AND CODE = CD_USE_TYPE) AS CD_USE_TYPE , BIG_SIZE_YN , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='SE_INSPECTION_CODE' AND CODE = SE_INSPECTION_CODE ) AS SE_INSPECTION_CODE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='INSPECTION_TYPE' AND CODE = INSPECTION_TYPE ) AS INSPECTION_TYPE , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='INSPECTION_TYPE' AND CODE = INSPECTION_TYPE_A ) AS INSPECTION_TYPE_A , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='INSPECTION_TYPE' AND CODE = INSPECTION_TYPE_B ) AS INSPECTION_TYPE_B , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='SE_INSPECTION_CODE' AND CODE = XRAY_INSPECTION_CODE ) AS XRAY_INSPECTION_CODE , AR_TIME , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='XRAY_LINE_NO' AND CODE = XRAY_LINE_NO ) AS XRAY_LINE_NO , XRAY_SCAN_CT , XRAY_IMAGE_CT , OD_JOB_NO , HOLD_YN , (SELECT CODE +'.'+ NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE ='HOLD_CODE' AND CODE = HOLD_CODE ) AS HOLD_CODE , HOLD_REASON , HOLD_RELEASE_YN , HOLD_RELEASE_ATTN , HOLD_RELEASE_DATE , CUSTOMER_CODE , CUSTOMER_NAME , SPECIAL_CODE_1 , SPECIAL_CODE_2 , SPECIAL_CODE_3 , ORIG_COUNTRY , REFERENCE_NO FROM (
