/* BmsChargeMapper.selectEstiBmsEstimateList : 창고료 리스트 조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT , SUM(AA.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT , SUM(AA.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT FROM (
) AA

/* BmsChargeMapper.selectEstimateListByInNoList : 메뉴_창고료정산, 프린트시, 반입번호로 창고료 리스트 조회 */ SELECT esti.* , code.NAME AS APPLY_CLASS_NAME FROM TB_BMS_ESTIMATE esti LEFT JOIN ( SELECT
NAME_${userLanguage}
NAME_DEFAULT
AS NAME , CODE FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = #{groupCode} ) code ON code.CODE = esti.APPLY_CLASS WHERE esti.ESTIMATE_DATE >= CONVERT(CHAR(10), #{startEstimateDate}, 23) AND esti.ESTIMATE_DATE <= CONVERT(CHAR(10), #{endEstimateDate}, 23) AND esti.CUSTOMER_CODE <> '1098302763'

/* BmsChargeMapper.selectBmsOutListByMrnMsnOfCargoNo : MRN + MSN 으로 화물관리번호 반출 리스트 조회 */
SELECT 
	OUT_CT
	, OUT_WT
FROM TB_BMS_OUT WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO LIKE #{mrn} + #{msn} + '%';

/* BmsChargeMapper.selectApplyClassNameList : 메뉴_창고료정산, 프린트시, 창고료조회시 요율구분 리스트 조회 */
SELECT


		NAME_${userLanguage}


		NAME_DEFAULT


	, CODE
FROM TB_SMS_CODE_DETAIL
WHERE ENT_CODE = #{srchEntCode} 
    AND GROUP_CODE = #{groupCode}

/* BmsChargeMapper.selectTcrNoFromEntBusOtion : TCR_NO 조회 */
SELECT
	SET_VALUE AS TCR_NO
FROM TB_SMS_ENT_BUS_OPTION
WHERE ENT_CODE = #{srchEntCode}
	AND ENT_BUSINESS_CODE = #{srchEntBusinessCode}
	AND SOLUTION = 'BMS'
    AND OPTION_CODE = 'A08'

mapper.update:
/* BmsChargeMapper.updateTcrNoFromEntBusOtion  : TCR_NO 업데이트 */
UPDATE TB_SMS_ENT_BUS_OPTION

    SET_VALUE    = #{tcrNo},
	UPDATE_USER_ID = #{updateUserId},
	UPDATE_DATE_TIME = GETDATE()

WHERE ENT_CODE = #{srchEntCode}
	AND ENT_BUSINESS_CODE = #{srchEntBusinessCode}
	AND SOLUTION = 'BMS'
    AND OPTION_CODE = 'A08'

