/* BmsChargeMapper.selectBmsApplyNoByEstimateDate  : 발행번호 Max 매출일자 기준 조회 */
SELECT  FORMAT( ISNULL(MAX(APPLY_NO),0) +1,'0000') AS  APPLY_NO


     , dbo.GET_DATE_DIFF_WORK_DAYS(#{srchCarryinDate}, #{srchEstimateDate}) AS STORAGE_DAYS
     , DATEDIFF(DAY, #{srchCarryinDate}, #{srchEstimateDate}) AS STORAGE_ALL_DAYS
FROM TB_BMS_ESTIMATE
WHERE APPLY_CLASS =#{srchApplyClass} AND ESTIMATE_DATE =#{srchEstimateDate} AND ESTIMATE_NO <> #{srchEstimateNo}

/* BmsChargeMapper.selectBmsCustomerInfo : 계산서 정산 번호 리턴 */ SELECT TOP 1 A.CUSTOMER_CODE , A.CUSTOMER_NAME , C.ATTN , A.ATTN_HP , C.TEL , C.EMAIL , dbo.Cryptography(A.REGISTRATION_CODE, B.BUSINESS_ID , 1) AS BUSINESS_NO /* 확정시 이곳 변경 예정 */ from TB_SMS_CUSTOMER A LEFT JOIN VTB_SMS_BUSINESS_REG_INFO B ON B.REGISTRATION_CODE = A.REGISTRATION_CODE AND B.ENT_CODE = A.ENT_CODE LEFT JOIN TB_SMS_CUSTOMER_ATTN C ON C.ENT_CODE = A.ENT_CODE AND C.CUSTOMER_CODE = A.CUSTOMER_CODE AND C.EBILL_YN = 'Y' AND C.EMAIL_USE_YN = 'Y' WHERE A.ENT_CODE = #{entCode}
AND dbo.Cryptography(A.REGISTRATION_CODE, B.BUSINESS_ID , 1) = #{companyBusinessNo}
AND A.CUSTOMER_CODE = #{customerCode}

