/* BmsChargeMapper.selectOneEstimate  : 창고료 상세 조회 */
SELECT TOP 1
*
, (SELECT USER_NAME FROM TB_SMS_USER  WHERE USER_ID = A.REGISTER_USER_ID) AS REGISTER_USER_NAME
, (SELECT USER_NAME FROM TB_SMS_USER  WHERE USER_ID = A.UPDATE_USER_ID) AS UPDATE_USER_NAME
FROM
TB_BMS_ESTIMATE A
where (1=1)


		AND IN_NO = #{inNo}


		AND OUT_PLAN_NO = #{outPlanNo}


		AND OUT_NO = #{outNo}


		AND ESTIMATE_NO = #{estimateNo}


ORDER BY ESTIMATE_NO DESC

/* BmsChargeMapper.selectCustomerOfInOut : 반입(with 반출)의 화주 조회 */ SELECT TOP 1 _in.CUSTOMER_CODE AS IN_CUSTOMER_CODE , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER cus INNER JOIN VTB_SMS_BUSINESS_REG_INFO tbri ON tbri.ENT_CODE = cus.ENT_CODE AND tbri.REGISTRATION_CODE = cus.REGISTRATION_CODE WHERE cus.ENT_CODE = #{entCode} AND cus.CUSTOMER_CODE = _in.CUSTOMER_CODE) AS IN_CUSTOMER_NAME , _out.CUSTOMER_CODE AS OUT_CUSTOMER_CODE , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER cus INNER JOIN VTB_SMS_BUSINESS_REG_INFO tbri ON tbri.ENT_CODE = cus.ENT_CODE AND tbri.REGISTRATION_CODE = cus.REGISTRATION_CODE WHERE cus.ENT_CODE = #{entCode} AND cus.CUSTOMER_CODE = _out.CUSTOMER_CODE) AS OUT_CUSTOMER_NAME , _in.* FROM TB_BMS_IN AS _in WITH (NOLOCK) LEFT JOIN TB_BMS_OUT AS _out WITH (NOLOCK) ON _out.IN_NO = _in.IN_NO where (1=1)
AND _in.IN_NO = #{inNo}
AND _out.OUT_PLAN_NO = #{outPlanNo}
AND _out.OUT_NO = #{outNo}
AND 1 = 0

	/* BmsChargeMapper.checkCustomerInfo  : 사업자정보 조회 */
	SELECT count(*) 
	FROM TB_SMS_CUSTOMER cus
   	INNER JOIN TB_SMS_BUSINESS_REG_INFO tbri ON tbri.ENT_CODE = cus.ENT_CODE AND tbri.REGISTRATION_CODE = cus.REGISTRATION_CODE
   	WHERE cus.ENT_CODE = #{entCode}
   		AND cus.CUSTOMER_CODE = #{customerCode}

