mapper.select:
/* BmsChargeMapper.selectBmsCustomerChageInfo : 창고료정산 > 화주정보 팝업 > 화주 조회 */ SELECT TOP 1 cus.CUSTOMER_CODE , cus.CUSTOMER_NAME , cus.TEL , attn.ATTN_ID , attn.ATTN , attn.TEL AS EBILL_TEL , attn.EMAIL , cus.ADDRESS , cus.ADDRESS_A , reg.BUSINESS_ID AS BUSINESS_NO , reg.BUSINESS_CONDITION , reg.BUSINESS_TYPE , reg.BUSINESS_PRESIDENT , cus.REGISTRATION_CODE FROM TB_SMS_CUSTOMER cus
LEFT JOIN TB_SMS_CUSTOMER_BUSINESS cbus ON cbus.ENT_CODE = cus.ENT_CODE AND cbus.CUSTOMER_CODE = cus.CUSTOMER_CODE
LEFT JOIN TB_SMS_CUSTOMER_ATTN attn ON attn.ENT_CODE = cus.ENT_CODE AND attn.CUSTOMER_CODE = cus.CUSTOMER_CODE AND attn.EBILL_YN = 'Y' AND attn.EMAIL_USE_YN = 'Y'
LEFT JOIN VTB_SMS_BUSINESS_REG_INFO reg ON reg.REGISTRATION_CODE = cus.REGISTRATION_CODE AND reg.ENT_CODE = cus.ENT_CODE
WHERE cus.ENT_CODE = #{entCode}
AND cus.CUSTOMER_CODE = #{customerCode}
AND (reg.BUSINESS_ID = #{businessNo} OR cus.CUSTOMER_CODE = #{businessNo})
ORDER BY attn.ATTN_ID

/* BmsChargeMapper.selectBmsBusRegistrationCode : 사업자정보 관리코드 조회 */
SELECT
	TOP 1 REGISTRATION_CODE
FROM VTB_SMS_BUSINESS_REG_INFO
WHERE ENT_CODE = #{entCode}
AND BUSINESS_ID = #{businessNo}

/* BmsChargeMapper.selectBmsCustomerRegistrationCode : 화주사업자정보 관리코드 생성 */
SELECT
	 CONCAT(#{entCode},REPLICATE('0',5-LEN(ISNULL(SUBSTRING(MAX(REGISTRATION_CODE),6,5),0)+1)) ,ISNULL(SUBSTRING(MAX(REGISTRATION_CODE),6,5),0)+1) AS REGISTRATION_CODE
FROM TB_SMS_BUSINESS_REG_INFO
WHERE ENT_CODE = #{entCode}

mapper.insert:
/* BmsChargeMapper.insertBmsCustomerChargeInfo : 화주 생성 */ INSERT INTO TB_SMS_CUSTOMER ( ENT_CODE ,CUSTOMER_CODE ,CUSTOMER_GROUP ,CUSTOMER_TYPE ,CUSTOMER_BUS_TYPE ,REGISTRATION_CODE ,HEAD_OFFICE_YN ,LANGUAGE_CODE ,CUSTOMER_NAME ,CUSTOMER_NAME_ENG ,ADDRESS ,ADDRESS_A ,TEL ,INVOICE_PERIOD ,PRICE_SETTLEMENT_TYPE ,PRICE_SETTLEMENT_DAY ,PRICE_PREPAID_YN ,CREDIT_RATING ,CREDIT_DAY ,CREDIT_LIMIT_AMOUNT ,CURRENCY_CODE ,EXRATE_TYPE ,EXRATE_ROUND_TYPE ,AMOUNT_ROUND_TYPE ,EBILL_SEND_YN ,EMBARGO_YN ,USE_YN ,BUSINESS_SETTLEMENT_YEAR ,USE_CONFIRM_YN ,INVOICE_SLIP_TRANS_YN ,CREATE_TYPE ,L_AR_YN ,L_AP_YN ,O_AR_YN ,O_AP_YN ,FSC_YN ,SCC_YN ,AR_DC_RATE ,CONSOL_USE_YN ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME ) VALUES ( #{entCode} ,#{customerCode} ,#{customerCode} ,'CU' ,'1' ,#{registrationCode} ,'N' ,'KOR' ,#{customerName} ,#{customerName} ,#{address} ,#{addressA} ,#{tel} ,'TO-D' ,'CASH' ,0 ,'N' ,'C' ,0 ,0 ,'KRW' ,'BUYING' ,1 ,1 ,'Y' ,'N' ,'Y' ,0 ,'Y' ,'Y' ,'G1' ,'Y' ,'Y' ,'Y' ,'Y' ,'Y' ,'Y' ,0 ,'N' ,#{userId} ,GETDATE() ,#{userId} ,GETDATE() );
INSERT INTO TB_SMS_CUSTOMER_BUSINESS ( ENT_CODE ,CUSTOMER_CODE ,ENT_BUSINESS_CODE ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME ) VALUES( #{entCode} ,#{customerCode} ,#{entBusinessCode} ,#{userId} ,GETDATE() ,#{userId} ,GETDATE() );
INSERT INTO TB_SMS_CUSTOMER_ATTN ( ENT_CODE ,CUSTOMER_CODE ,ATTN_ID ,SOLUTION ,BOUND ,BOUND_TYPE ,ATTN_JOB_TYPE ,ATTN ,TEL ,EMAIL ,SMS_USE_YN ,EMAIL_USE_YN ,EBILL_YN ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME ) VALUES( #{entCode} ,#{customerCode} ,#{customerCode} ,'SAS' ,'COM' ,'COM' ,'03' ,'.' ,#{ebillTel} ,#{email} ,'N' ,'Y' ,'Y' ,#{userId} ,GETDATE() ,#{userId} ,GETDATE() );
MERGE INTO TB_SMS_BUSINESS_REG_INFO AS A USING ( SELECT #{registrationCode} AS registrationCode ,#{entCode} AS entCode ) AS B ON A.REGISTRATION_CODE = B.registrationCode AND A.ENT_CODE = B.entCode WHEN MATCHED THEN UPDATE SET A.CUSTOMER_YN = 'Y' ,A.CORPORATE_YN = 'Y' ,A.BUSINESS_COMPANY_NAME= #{customerName} ,A.BUSINESS_PRESIDENT = #{businessPresident} ,A.BUSINESS_OPEN_DATE = CASE WHEN A.BUSINESS_OPEN_DATE IS NULL THEN CAST(GETDATE() AS DATE) ELSE BUSINESS_OPEN_DATE END ,A.BUSINESS_CONDITION = #{businessCondition} ,A.BUSINESS_TYPE = #{businessType} ,A.ADDRESS = #{address} ,A.ADDRESS_A = #{addressA} ,A.COMPANY_NAME_ENG = #{customerName} ,A.ADDRESS_ENG = #{address} ,A.UPDATE_USER_ID = #{userId} ,A.UPDATE_DATE_TIME = GETDATE() WHEN NOT MATCHED THEN INSERT ( REGISTRATION_CODE ,ENT_CODE ,ENT_BUSINESS_CODE ,PARENT_REG_CODE ,REG_SEQ_NO ,CUSTOMER_YN ,CORPORATE_YN ,BUSINESS_ID ,BUSINESS_COMPANY_NAME ,BUSINESS_PRESIDENT ,BUSINESS_OPEN_DATE ,BUSINESS_CONDITION ,BUSINESS_TYPE ,ADDRESS ,ADDRESS_A ,COMPANY_NAME_ENG ,ADDRESS_ENG ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME ) VALUES( #{registrationCode} ,#{entCode} ,#{entBusinessCode} ,'' ,1 ,'Y' ,'Y' ,dbo.Cryptography(#{registrationCode}, #{businessNo}, 0) ,#{customerName} ,#{businessPresident} ,CAST(GETDATE() AS DATE) ,#{businessCondition} ,#{businessType} ,#{address} ,#{addressA} ,#{customerName} ,#{address} ,#{userId} ,GETDATE() ,#{userId} ,GETDATE() );

mapper.update:
/* BmsChargeMapper.updateBmsCustomerChargeInfo  : 화주 정보 변경 */
UPDATE TB_SMS_CUSTOMER

	 CUSTOMER_NAME		= #{customerName}
	,CUSTOMER_NAME_ENG	= #{customerName}
	,REGISTRATION_CODE	= #{registrationCode}
	,ADDRESS			= #{address}
	,ADDRESS_A			= #{addressA}
	,TEL				= #{tel}
	,UPDATE_USER_ID		= #{userId}
	,UPDATE_DATE_TIME	= GETDATE()

WHERE ENT_CODE = #{entCode}
AND CUSTOMER_CODE = #{customerCode};

MERGE INTO TB_SMS_CUSTOMER_ATTN AS A
USING (
	SELECT
		 #{entCode} AS entCode
		,#{customerCode} AS customerCode
		,#{attnId} AS attnId
) AS B
ON A.ENT_CODE = B.entCode
AND A.CUSTOMER_CODE = B.customerCode
AND A.ATTN_ID = B.attnId
WHEN MATCHED THEN
	UPDATE SET
		 A.ATTN_ID			= #{customerCode}
		,A.TEL				= #{ebillTel}
		,A.EMAIL			= #{email}
		,A.UPDATE_USER_ID	= #{userId}
		,A.UPDATE_DATE_TIME	= GETDATE()
WHEN NOT MATCHED THEN
	INSERT (
		 ENT_CODE
		,CUSTOMER_CODE
		,ATTN_ID
		,SOLUTION
		,BOUND
		,BOUND_TYPE
		,ATTN_JOB_TYPE
		,ATTN
		,TEL
		,EMAIL
		,SMS_USE_YN
		,EMAIL_USE_YN
		,EBILL_YN
		,REGISTER_USER_ID
		,REGISTER_DATE_TIME
		,UPDATE_USER_ID
		,UPDATE_DATE_TIME
	) VALUES(
		 #{entCode}
		,#{customerCode}
		,#{customerCode}
		,'SAS'
		,'COM'
		,'COM'
		,'03'
		,'.'
		,#{ebillTel}
		,#{email}
		,'N'
		,'Y'
		,'Y'
		,#{userId}
		,GETDATE()
		,#{userId}
		,GETDATE()
	);

MERGE INTO TB_SMS_BUSINESS_REG_INFO AS A
USING (
	SELECT
		 #{registrationCode} AS registrationCode
		,#{entCode} AS entCode
) AS B
ON A.REGISTRATION_CODE = B.registrationCode
AND A.ENT_CODE = B.entCode
WHEN MATCHED THEN
	UPDATE SET
		 A.CUSTOMER_YN			= 'Y'
		,A.CORPORATE_YN			= 'Y'
		,A.BUSINESS_COMPANY_NAME= #{customerName}
		,A.BUSINESS_PRESIDENT 	= #{businessPresident}
		,A.BUSINESS_OPEN_DATE	= CASE WHEN A.BUSINESS_OPEN_DATE IS NULL THEN CAST(GETDATE() AS DATE) ELSE BUSINESS_OPEN_DATE END
		,A.BUSINESS_CONDITION	= #{businessCondition}
		,A.BUSINESS_TYPE		= #{businessType}
		,A.ADDRESS				= #{address}
		,A.ADDRESS_A			= #{addressA}
		,A.COMPANY_NAME_ENG		= #{customerName}
		,A.ADDRESS_ENG			= #{address}
		,A.UPDATE_USER_ID		= #{userId}
		,A.UPDATE_DATE_TIME		= GETDATE()
WHEN NOT MATCHED THEN
	INSERT (
		 REGISTRATION_CODE
		,ENT_CODE
		,ENT_BUSINESS_CODE
		,PARENT_REG_CODE
		,REG_SEQ_NO
		,CUSTOMER_YN
		,CORPORATE_YN
		,BUSINESS_ID
		,BUSINESS_COMPANY_NAME
		,BUSINESS_PRESIDENT
		,BUSINESS_OPEN_DATE
		,BUSINESS_CONDITION
		,BUSINESS_TYPE
		,ADDRESS
		,ADDRESS_A
		,COMPANY_NAME_ENG
		,ADDRESS_ENG
		,REGISTER_USER_ID
		,REGISTER_DATE_TIME
		,UPDATE_USER_ID
		,UPDATE_DATE_TIME
	) VALUES(
		 #{registrationCode}
		,#{entCode}
		,#{entBusinessCode}
		,''
		,1
		,'Y'
		,'Y'
		,dbo.Cryptography(#{registrationCode}, #{businessNo}, 0)
		,#{customerName}
		,#{businessPresident}
		,CAST(GETDATE() AS DATE)
		,#{businessCondition}
		,#{businessType}
		,#{address}
		,#{addressA}
		,#{customerName}
		,#{address}
		,#{userId}
		,GETDATE()
		,#{userId}
		,GETDATE()
	);
